  src: url(https://fonts.gstatic.com/s/unbounded/v12/Yq6W-LOTXCb04q32xlpwu8Zf.woff2) format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;

input.content:
@font-face {
  font-family: "Unbounded";
  src: url("/fonts/unbounded-latin.woff2") format("woff2");
  font-weight: 400 900;
  font-display: swap;
}
@font-face {
  font-family: "Space Grotesk";
  src: url("/fonts/space-grotesk-latin.woff2") format("woff2");
  font-weight: 400 700;
  font-display: swap;
}
@font-face {
  font-family: "DM Mono";
  src: url("/fonts/dm-mono-400.woff2") format("woff2");
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "DM Mono";
  src: url("/fonts/dm-mono-500.woff2") format("woff2");
  font-weight: 500;
  font-display: swap;
}

:root {
  --ink: #f8f3ff;
  --muted: rgba(239, 224, 255, 0.48);
  --dim: rgba(239, 224, 255, 0.22);
  --line: rgba(240, 220, 255, 0.16);
  --panel: rgba(10, 2, 18, 0.42);
  --accent: #ff3fba;
  --accent-2: #b897ff;
  --accent-3: #6ff7ff;
  --acid: #d8ff5e;
  --bg: #050008;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  height: 100%;
  overflow: hidden;
  background: var(--bg);
}

body {
  color: var(--ink);
  font-family: "Space Grotesk", sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
  user-select: none;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  font: inherit;
  color: inherit;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(circle at 62% 45%, rgba(72, 12, 105, 0.38), transparent 45%),
    #050008;
}

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: grab;
}

#scene:active {
  cursor: grabbing;
}

/* ------------------------------------------------------------------ */
/* cinematic overlays                                                   */
/* ------------------------------------------------------------------ */

.fx-grain,
.fx-scanlines,
.fx-vignette,
.fx-flash {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.fx-grain {
  z-index: 20;
  opacity: 0.09;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.78' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.8'/%3E%3C/svg%3E");
  animation: grain 0.55s steps(2) infinite;
}

@keyframes grain {
  0% { transform: translate3d(0, 0, 0) scale(1.08); }
  25% { transform: translate3d(-2%, 1%, 0) scale(1.08); }
  50% { transform: translate3d(1%, -2%, 0) scale(1.08); }
  75% { transform: translate3d(2%, 2%, 0) scale(1.08); }
  100% { transform: translate3d(-1%, -1%, 0) scale(1.08); }
}

.fx-scanlines {
  z-index: 19;
  opacity: 0.2;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0,
    transparent 3px,
    rgba(7, 0, 12, 0.28) 4px
  );
  mix-blend-mode: multiply;
}

.fx-vignette {
  z-index: 18;
  background:
    radial-gradient(ellipse at 57% 46%, transparent 32%, rgba(5, 0, 8, 0.22) 65%, rgba(5, 0, 8, 0.82) 100%),
    linear-gradient(90deg, rgba(5, 0, 8, 0.55), transparent 28%, transparent 72%, rgba(5, 0, 8, 0.4));
}

.fx-flash {
  z-index: 25;
  opacity: 0;
  background: white;
  mix-blend-mode: screen;
  transition: opacity 0.7s var(--ease);
}

body.is-flashing .fx-flash {
  opacity: 0.22;
  transition: opacity 0.04s linear;
}

body.is-glitching #app {
  animation: glitch-shake 0.34s steps(2) both;
}

@keyframes glitch-shake {
  0% { transform: translate(0, 0); filter: hue-rotate(0deg); }
  20% { transform: translate(-7px, 2px); filter: hue-rotate(28deg) contrast(1.3); }
  40% { transform: translate(5px, -4px); filter: hue-rotate(-22deg); }
  60% { transform: translate(-4px, -1px) skewX(0.5deg); filter: contrast(1.6); }
  80% { transform: translate(3px, 3px); filter: hue-rotate(14deg); }
  100% { transform: translate(0, 0); filter: none; }
}

/* ------------------------------------------------------------------ */
/* top bar                                                             */
/* ------------------------------------------------------------------ */

.topbar {
  position: absolute;
  z-index: 30;
  top: 0;
  left: 0;
  right: 0;
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 27px 34px;
  padding-top: max(27px, env(safe-area-inset-top));
  border-bottom: 1px solid transparent;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  color: var(--ink);
  text-decoration: none;
  justify-self: start;
}

.brand-glyph {
  display: grid;
  place-items: center;
  width: 35px;
  height: 35px;
  border: 1px solid rgba(255, 255, 255, 0.32);
  border-radius: 50%;
  font-size: 15px;
  color: var(--accent-3);
  box-shadow: inset 0 0 18px rgba(111, 247, 255, 0.12), 0 0 22px rgba(111, 247, 255, 0.12);
  animation: glyph-spin 12s linear infinite;
}

@keyframes glyph-spin {
  to { transform: rotate(360deg); }
}

.brand-lockup {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.brand-lockup strong {
  font-family: "Unbounded", sans-serif;
  font-weight: 800;
  font-size: 19px;
  line-height: 1;
  letter-spacing: 0.1em;
}

.brand-lockup small {
  font-family: "DM Mono", monospace;
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--muted);
}

.divinity {
  display: flex;
  align-items: center;
  gap: 9px;
  justify-self: center;
  font-family: "DM Mono", monospace;
  font-size: 9px;
  letter-spacing: 0.19em;
  color: rgba(237, 222, 255, 0.62);
  white-space: nowrap;
}

.divinity em {
  font-style: normal;
  color: var(--dim);
  margin-left: 10px;
}

.divinity-orbit {
  position: relative;
  width: 11px;
  height: 11px;
  border: 1px solid rgba(216, 255, 94, 0.45);
  border-radius: 50%;
}

.divinity-orbit i {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--acid);
  transform: translate(-50%, -50%);
  box-shadow: 0 0 8px var(--acid);
  animation: core-pulse 1.8s ease-in-out infinite;
}

@keyframes core-pulse {
  50% { transform: translate(-50%, -50%) scale(0.5); opacity: 0.5; }
}

.top-actions {
  display: flex;
  gap: 8px;
  justify-self: end;
}

.icon-btn {
  height: 34px;
  border: 1px solid var(--line);
  background: rgba(10, 2, 18, 0.2);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  cursor: pointer;
  transition: border-color 0.3s, background 0.3s, color 0.3s;
}

.icon-btn:hover {
  border-color: rgba(255, 255, 255, 0.52);
  background: rgba(255, 255, 255, 0.07);
}

.sound-btn {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 13px;
  font-family: "DM Mono", monospace;
  font-size: 8px;
  letter-spacing: 0.15em;
  color: var(--muted);
}

.sound-bars {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 12px;
}

.sound-bars i {
  display: block;
  width: 1.5px;
  height: 25%;
  background: currentColor;
  transition: height 0.25s var(--ease), background 0.25s;
}

body.sound-on .sound-bars i {
  background: var(--accent-3);
  animation: sound-bar 0.7s ease-in-out infinite alternate;
}

body.sound-on .sound-bars i:nth-child(2) { animation-delay: -0.2s; }
body.sound-on .sound-bars i:nth-child(3) { animation-delay: -0.45s; }
body.sound-on .sound-bars i:nth-child(4) { animation-delay: -0.1s; }

@keyframes sound-bar {
  from { height: 20%; }
  to { height: 100%; }
}

.info-btn {
  width: 34px;
  border-radius: 50%;
  font-family: "DM Mono", monospace;
  font-size: 11px;
  color: var(--muted);
}

/* ------------------------------------------------------------------ */
/* hero type                                                           */
/* ------------------------------------------------------------------ */

.interface {
  position: absolute;
  z-index: 29;
  inset: 0;
  pointer-events: none;
}

.hero-copy {
  position: absolute;
  left: clamp(22px, 4.2vw, 76px);
  top: 19.5%;
  width: min(44vw, 660px);
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
  font-family: "DM Mono", monospace;
  font-size: 9px;
  font-weight: 500;
  letter-spacing: 0.28em;
  color: rgba(246, 235, 255, 0.55);
}

.eyebrow span {
  display: inline-grid;
  place-items: center;
  width: 23px;
  height: 23px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 50%;
  color: var(--accent-3);
  letter-spacing: 0;
}

.hero-copy h1 {
  font-family: "Unbounded", sans-serif;
  font-weight: 800;
  font-size: clamp(46px, 5.7vw, 102px);
  line-height: 0.87;
  letter-spacing: -0.072em;
  text-transform: uppercase;
  transform-origin: left center;
}

.line {
  display: block;
  position: relative;
  width: max-content;
}

.line-1 {
  color: rgba(249, 241, 255, 0.96);
  text-shadow: 0 0 60px rgba(196, 121, 255, 0.22);
}

.line-2 {
  margin-left: 0.58em;
  font-size: 0.86em;
  color: transparent;
  -webkit-text-stroke: 1px rgba(248, 235, 255, 0.58);
  text-shadow: none;
}

.line-3 {
  margin-top: 0.07em;
  font-size: 0.96em;
  color: transparent;
  background: linear-gradient(
    178deg,
    #ffffff 1%,
    #ffd8f5 19%,
    #ff4bbd 38%,
    #7f38ff 57%,
    #5bf1ff 76%,
    #ffffff 100%
  );
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 6px 26px rgba(255, 55, 186, 0.28));
  -webkit-text-stroke: 0.5px rgba(255, 255, 255, 0.14);
}

.line-3::before,
.line-3::after {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  z-index: -1;
  opacity: 0;
  background: inherit;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  pointer-events: none;
}

body.is-casting .line-3::before {
  opacity: 0.8;
  transform: translate(4px, -2px);
  filter: hue-rotate(35deg);
  animation: type-glitch 0.35s steps(2) both;
}

body.is-casting .line-3::after {
  opacity: 0.65;
  transform: translate(-4px, 2px);
  filter: hue-rotate(-40deg);
  animation: type-glitch-2 0.35s steps(2) both;
}

@keyframes type-glitch {
  50% { clip-path: inset(10% 0 56% 0); transform: translate(8px, -3px); }
}
@keyframes type-glitch-2 {
  50% { clip-path: inset(52% 0 14% 0); transform: translate(-9px, 2px); }
}

.lede {
  width: 315px;
  margin-top: 26px;
  padding-left: 15px;
  border-left: 1px solid rgba(255, 255, 255, 0.22);
  font-size: 13px;
  line-height: 1.55;
  letter-spacing: 0.012em;
  color: rgba(242, 231, 255, 0.62);
}

.lede span {
  display: block;
  color: rgba(242, 231, 255, 0.32);
}

/* ------------------------------------------------------------------ */
/* power dock                                                          */
/* ------------------------------------------------------------------ */

.power-dock {
  position: absolute;
  top: 26%;
  right: clamp(22px, 3.8vw, 68px);
  width: min(272px, 22vw);
  min-width: 232px;
  pointer-events: auto;
}

.dock-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: "DM Mono", monospace;
  font-size: 8px;
  letter-spacing: 0.25em;
  color: rgba(244, 232, 255, 0.45);
}

.dock-index {
  color: var(--dim);
  letter-spacing: 0.12em;
}

.dock-line {
  height: 1px;
  margin: 11px 0 7px;
  background: linear-gradient(90deg, rgba(255, 255, 255, 0.32), transparent);
}

.power {
  position: relative;
  display: grid;
  grid-template-columns: 18px 27px 1fr 15px;
  align-items: center;
  gap: 7px;
  width: 100%;
  min-height: 55px;
  padding: 9px 0;
  text-align: left;
  border: 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: transparent;
  cursor: pointer;
  overflow: hidden;
  transition: padding 0.35s var(--ease), border-color 0.3s;
}

.power::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(90deg, rgba(255, 63, 186, 0.15), transparent 76%);
  transform: translateX(-102%);
  transition: transform 0.45s var(--ease);
}

.power:hover::before,
.power:focus-visible::before,
.power.is-active::before {
  transform: translateX(0);
}

.power:hover,
.power:focus-visible,
.power.is-active {
  padding-left: 9px;
  border-color: rgba(255, 255, 255, 0.32);
  outline: none;
}

.power-num {
  font-family: "DM Mono", monospace;
  font-size: 7px;
  color: var(--dim);
  align-self: start;
  padding-top: 4px;
}

.power-icon {
  font-size: 18px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.45);
  transition: color 0.3s, transform 0.45s var(--ease), text-shadow 0.3s;
}

.power:hover .power-icon,
.power.is-active .power-icon {
  color: var(--accent-3);
  transform: rotate(90deg) scale(1.15);
  text-shadow: 0 0 14px var(--accent-3);
}

.power-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.power-copy strong {
  font-family: "Unbounded", sans-serif;
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.06em;
}

.power-copy small {
  font-family: "DM Mono", monospace;
  font-size: 6.5px;
  letter-spacing: 0.12em;
  color: rgba(243, 231, 255, 0.34);
}

.power-arrow {
  font-size: 12px;
  color: var(--dim);
  transform: translate(-4px, 4px);
  opacity: 0;
  transition: opacity 0.3s, transform 0.35s var(--ease);
}

.power:hover .power-arrow,
.power.is-active .power-arrow {
  opacity: 1;
  transform: translate(0, 0);
}

.power-all .power-copy strong {
  background: linear-gradient(90deg, var(--accent-3), #fff, var(--accent));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/* ------------------------------------------------------------------ */
/* telemetry / transmission                                            */
/* ------------------------------------------------------------------ */

.telemetry {
  position: absolute;
  right: clamp(22px, 3.8vw, 68px);
  bottom: 118px;
  display: flex;
  align-items: center;
  gap: 11px;
  font-family: "DM Mono", monospace;
  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--dim);
}

.telemetry-ring {
  position: relative;
  width: 49px;
  height: 49px;
}

.telemetry-ring svg {
  transform: rotate(-90deg);
  width: 100%;
  height: 100%;
}

.telemetry-ring circle {
  fill: none;
  stroke-width: 1.3;
}

.ring-bg {
  stroke: rgba(255, 255, 255, 0.1);
}

.ring-fill {
  stroke: var(--accent-3);
  stroke-dasharray: 276.46;
  stroke-dashoffset: 0;
  filter: drop-shadow(0 0 4px var(--accent-3));
  transition: stroke-dashoffset 1.2s var(--ease), stroke 0.5s;
}

.telemetry-core {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "DM Mono", monospace;
  font-size: 10px;
  color: var(--ink);
}

.telemetry-core span {
  font-size: 6px;
  color: var(--muted);
  margin-top: 5px;
}

.transmission {
  position: absolute;
  left: clamp(22px, 4.2vw, 76px);
  bottom: 116px;
  width: min(335px, 35vw);
  padding-top: 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
}

.transmission-label {
  display: flex;
  gap: 7px;
  align-items: center;
  font-family: "DM Mono", monospace;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.transmission-label i {
  font-style: normal;
  color: var(--accent);
}

.transmission-label b {
  font-weight: 500;
  color: var(--accent-3);
  letter-spacing: 0.14em;
}

.transmission p {
  margin-top: 8px;
  font-size: 12px;
  line-height: 1.4;
  color: rgba(245, 235, 255, 0.55);
  min-height: 2.8em;
  transition: opacity 0.35s;
}

.transmission p.is-changing {
  opacity: 0;
}

/* ------------------------------------------------------------------ */
/* footer                                                              */
/* ------------------------------------------------------------------ */

.bottombar {
  position: absolute;
  z-index: 30;
  left: 0;
  right: 0;
  bottom: 0;
  padding-bottom: env(safe-area-inset-bottom);
}

.ticker {
  overflow: hidden;
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(8, 1, 14, 0.2);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.ticker-track {
  display: flex;
  width: max-content;
  animation: ticker 34s linear infinite;
}

.ticker-track span {
  display: block;
  padding: 9px 0;
  font-family: "Unbounded", sans-serif;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.22em;
  color: rgba(247, 236, 255, 0.44);
  white-space: nowrap;
}

@keyframes ticker {
  to { transform: translateX(-50%); }
}

.footer-meta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 11px clamp(22px, 3.4vw, 60px) 13px;
  font-family: "DM Mono", monospace;
  font-size: 7px;
  letter-spacing: 0.15em;
  color: rgba(242, 229, 255, 0.32);
}

.footer-meta span {
  display: flex;
  align-items: center;
  gap: 7px;
}

.pulse-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent-3);
  box-shadow: 0 0 7px var(--accent-3);
  animation: core-pulse 2s ease-in-out infinite;
}

.footer-hint {
  color: rgba(242, 229, 255, 0.2) !important;
}

/* ------------------------------------------------------------------ */
/* modal                                                               */
/* ------------------------------------------------------------------ */

.modal {
  position: absolute;
  z-index: 60;
  top: 50%;
  left: 50%;
  width: min(530px, calc(100vw - 40px));
  padding: 42px 44px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background:
    linear-gradient(150deg, rgba(41, 5, 58, 0.94), rgba(7, 0, 13, 0.93)),
    rgba(5, 0, 8, 0.9);
  backdrop-filter: blur(30px);
  -webkit-backdrop-filter: blur(30px);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.6), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transform: translate(-50%, -47%) scale(0.96);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.4s var(--ease), transform 0.45s var(--ease), visibility 0.4s;
}

.modal.is-open {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, -50%) scale(1);
}

.modal h2 {
  margin: 14px 0 20px;
  font-family: "Unbounded", sans-serif;
  font-size: clamp(30px, 4vw, 46px);
  font-weight: 600;
  line-height: 0.98;
  letter-spacing: -0.05em;
}

.modal h2 em {
  font-family: Georgia, serif;
  font-weight: 400;
  color: var(--accent);
}

.modal > p:not(.eyebrow) {
  margin-bottom: 13px;
  font-size: 13px;
  line-height: 1.65;
  color: rgba(245, 235, 255, 0.58);
}

.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  transition: transform 0.3s, color 0.3s, border-color 0.3s;
}

.modal-close:hover {
  transform: rotate(90deg);
  color: white;
  border-color: white;
}

.modal-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin-top: 26px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  font-family: "DM Mono", monospace;
  font-size: 8px;
  letter-spacing: 0.13em;
  color: var(--muted);
}

