    const buckle = this.add(new THREE.Mesh(new THREE.OctahedronGeometry(0.07, 0), this.glowPink));
    buckle.position.set(0, 2.11, 0.205);
    buckle.scale.set(1, 1.5, 0.55);

    // Shoulder straps
    [-1, 1].forEach((s) => {
      const strapCurve = new THREE.CatmullRomCurve3([
