      color: "#ff9ce6",
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    const glowSprite = new THREE.Sprite(spriteMat);
    glowSprite.scale.setScalar(0.85);
    this.orb.add(glowSprite);
    this.orbGlow = glowSprite;

    this.orbRings = [];
    [0, 1, 2].forEach((i) => {
      const r = new THREE.Mesh(
        new THREE.TorusGeometry(0.15 + i * 0.03, 0.003, 4, 60),
        new THREE.MeshBasicMaterial({
          color: i === 1 ? "#6ff7ff" : "#ffd6ff",
          transparent: true,
          opacity: 0.65,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        })
      );
      r.rotation.set(Math.PI / 2 + i * 0.6, i * 0.7, i * 0.4);
      this.orb.add(r);
      this.orbRings.push(r);
    });

    // tiny star shards
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU;
      const shard = new THREE.Mesh(new THREE.TetrahedronGeometry(0.014, 0), i % 2 ? this.glowCyan : this.chrome);
      shard.position.set(Math.cos(a) * 0.3, Math.sin(a * 1.3) * 0.15, Math.sin(a) * 0.3);
      shard.userData = { angle: a, radius: 0.3, speed: 0.7 + Math.random() * 0.4 };
      this.orb.add(shard);
      this.orbRings.push(shard);
    }
  }

  setPointer(x, y) {
    this.pointer.set(x, y);
  }

  setPalette(palette) {
    if (palette.skin) this.targetPalette.skin = new THREE.Color(palette.skin);
    if (palette.hair) this.targetPalette.hair = new THREE.Color(palette.hair);
    if (palette.fabric) this.targetPalette.fabric = new THREE.Color(palette.fabric);
    if (palette.accent) this.targetPalette.accent = new THREE.Color(palette.accent);
    if (palette.accent2) this.targetPalette.accent2 = new THREE.Color(palette.accent2);
    if (palette.chrome) this.targetPalette.chrome = new THREE.Color(palette.chrome);
  }

  cast(power) {
    this.action = { power, time: 0 };
    this.auraStrength = 1.8;
    if (power === "destroy") {
      this.auraStrength = 2.6;
    }
  }

  update(dt, elapsed) {
    this.time = elapsed;
    const t = elapsed;

    // Palette easing
    this.skin.color.lerp(this.targetPalette.skin, dt * 1.8);
    this.hairMat.color.lerp(this.targetPalette.hair, dt * 1.8);
    this.fabricMat.color.lerp(this.targetPalette.fabric, dt * 1.8);
    this.fabricInnerMat.color.lerp(this.targetPalette.fabric.clone().offsetHSL(0.1, 0, 0.15), dt * 1.8);
    this.chrome.color.lerp(this.targetPalette.chrome, dt * 1.8);
    this.haloMat.emissive.lerp(this.targetPalette.accent2, dt * 1.8);

    // Idle breathing and contrapposto
    const breath = Math.sin(t * 1.25);
    this.group.position.y = breath * 0.012;
    this.group.rotation.y = Math.sin(t * 0.35) * 0.045 + this.pointer.x * 0.075;
    this.group.rotation.z = Math.sin(t * 0.42) * 0.008;
    this.torso.scale.set(1 + breath * 0.004, 1 + breath * 0.006, 1 + breath * 0.004);
    this.neck.rotation.z = Math.sin(t * 0.55) * 0.012;

    // Head follows the pointer with grace
    this.headGroup.rotation.y = this.pointer.x * 0.22 + Math.sin(t * 0.47) * 0.035;
    this.headGroup.rotation.x = this.pointer.y * -0.09 + Math.sin(t * 0.61) * 0.018;
    this.headGroup.rotation.z = Math.sin(t * 0.38) * 0.02;

    // Arm life
    const actionAge = this.action ? t - this.action.time : 99;
    let gesture = 0;
    if (this.action && actionAge < 1.6) {
      const p = actionAge / 1.6;
      gesture = Math.sin(p * Math.PI) * 0.1;
    }
    this.armR.rotation.z = Math.sin(t * 0.7) * 0.018 + gesture;
    this.armR.rotation.x = Math.sin(t * 0.55 + 1) * 0.016;
    this.armL.rotation.z = Math.sin(t * 0.62 + 2) * 0.015 - gesture * 0.4;
    this.armL.rotation.x = Math.sin(t * 0.48) * 0.015;

    // Halo motion
    this.crownRing.rotation.z = t * 0.11;
    this.crownRing2.rotation.z = -t * 0.18;
    this.headHalo.rotation.z = t * 0.08;
    this.headHalo.material.opacity = 0.38 + Math.sin(t * 0.9) * 0.12;
    this.haloMat.emissiveIntensity = 0.8 + Math.sin(t * 1.1) * 0.25;

    this.rings.forEach((ring) => {
      const d = ring.userData;
      ring.rotation.z = d.baseRz + Math.sin(t * d.speed + d.phase) * 0.12;
      ring.rotation.x = d.baseRx + Math.cos(t * d.speed * 0.8 + d.phase) * 0.035;
      ring.material.opacity = 0.32 + Math.sin(t * 0.5 + d.phase) * 0.1;
    });

    this.satellites.forEach(({ mesh, kind }) => {
      const u = mesh.userData;
      if (kind === "sat") {
        const ang = u.angle + t * u.speed;
        mesh.position.set(Math.cos(ang) * u.radius, u.ring.position.y + Math.sin(ang * 2) * 0.04, Math.sin(ang) * u.radius);
        mesh.rotation.x = t * 0.7;
        mesh.rotation.y = t * 0.9;
      } else if (kind === "crown") {
        const ang = u.angle + t * u.speed;
        mesh.position.set(Math.sin(ang) * u.radius, u.y + Math.sin(ang * 3 + t) * 0.018, Math.cos(ang) * u.radius);
        mesh.rotation.y = t * 0.4;
      } else if (kind === "orbit") {
        const ang = u.a + t * u.speed;
        mesh.position.set(Math.sin(ang) * u.r, u.y + Math.sin(t * 0.5 + u.a) * 0.09, Math.cos(ang) * u.r * 0.7 - 0.3);
        mesh.rotation.x += dt * u.spin;
        mesh.rotation.y += dt * u.spin * 0.7;
      }
    });

    // Dress ripple (vertices only, subtle)
    const pos = this.skirt.geometry.attributes.position;
    const arr = pos.array;
    const base = this.skirtBase;
    for (let i = 0; i < arr.length; i += 3) {
      const x = base[i];
      const z = base[i + 2];
      const y = base[i + 1];
      const angle = Math.atan2(x, z);
      const depth = clamp(1 - y / 2.1, 0, 1);
      const wave = Math.sin(angle * 4 + t * 1.6 + y * 2.2) * 0.035 * depth;
      arr[i] = x + Math.sin(angle) * wave;
      arr[i + 2] = z + Math.cos(angle) * wave;
    }
    pos.needsUpdate = true;
    this.skirt.geometry.computeVertexNormals();

    // Hair sway
    this.hairGroup.rotation.z = Math.sin(t * 0.55) * 0.012;
    this.hairGroup.rotation.x = Math.sin(t * 0.43) * 0.008;
    this.hairMeshes.forEach(({ mesh, phase }) => {
      mesh.rotation.z = Math.sin(t * 0.55 + phase) * 0.006;
    });

    // Orb
    const pulse = 1 + Math.sin(t * 2.2) * 0.06;
    this.orb.position.y = this.orbAnchor.position.y + Math.sin(t * 1.4) * 0.025;
    this.orbCore.scale.setScalar(pulse);
    this.orbGlow.scale.setScalar(0.8 + Math.sin(t * 2.1) * 0.06 + (actionAge < 1 ? 0.3 : 0));
    this.orbRings.forEach((obj, i) => {
      const u = obj.userData;
      if (u.radius) {
        const ang = u.angle + t * u.speed;
        obj.position.set(Math.cos(ang) * u.radius, Math.sin(ang * 1.7) * 0.1, Math.sin(ang) * u.radius);
        obj.rotation.x += dt * 0.9;
      } else {
        obj.rotation.z += dt * (0.2 + i * 0.05);
        obj.rotation.x += dt * 0.13;
      }
    });

    // Eyes glow with power
    const eyeGlow = 1.4 + Math.sin(t * 1.7) * 0.2 + (this.action ? Math.max(0, 1.4 - actionAge) * 1.8 : 0);
    this.eyes.forEach((eye) => {
      eye.material.opacity = 0.75;
      eye.scale.setScalar(1 + Math.sin(t * 2 + 1) * 0.05);
    });
    this.auraMat.uniforms.uStrength.value += (this.auraStrength - this.auraMat.uniforms.uStrength.value) * dt * 2.2;
    this.auraMat.uniforms.uTime.value = t;
    this.auraMat.uniforms.uColorA.value.lerp(this.targetPalette.accent, dt * 2);
    this.auraMat.uniforms.uColorB.value.lerp(this.targetPalette.accent2, dt * 2);
    this.auraStrength += (1 - this.auraStrength) * dt * 1.5;

    if (this.action) this.action.time = Math.min(this.action.time + dt, 99);

    // Hand anchor follows the hand gesture visually
    this.handAnchor.position.y = 2.21 + Math.sin(t * 1.7 + 1) * 0.02;
    this.orb.position.x = this.orbAnchor.position.x + Math.sin(t * 0.8) * 0.02;
    this.orb.position.z = this.orbAnchor.position.z + Math.cos(t * 0.7) * 0.02;
  }

  getHandWorldPosition() {
    return this.orb.getWorldPosition(new THREE.Vector3());
  }
}

import * as THREE from "three";

const TAU = Math.PI * 2;

function canvasTexture(size, draw) {
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext("2d");
  draw(ctx, size);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

function createSunTexture() {
  return canvasTexture(1024, (ctx, s) => {
    ctx.clearRect(0, 0, s, s);
    const cx = s / 2;
    const cy = s / 2;
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, s / 2);
    g.addColorStop(0, "rgba(255,246,255,1)");
    g.addColorStop(0.06, "rgba(255,190,246,1)");
    g.addColorStop(0.2, "rgba(255,64,187,0.88)");
    g.addColorStop(0.46, "rgba(120,32,255,0.28)");
    g.addColorStop(0.8, "rgba(46,5,76,0.04)");
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);

    ctx.globalCompositeOperation = "lighter";
    for (let i = 0; i < 7; i++) {
      ctx.beginPath();
      ctx.arc(cx, cy, s * (0.2 + i * 0.04), 0, TAU);
      ctx.strokeStyle = i % 2 ? "rgba(255,255,255,0.055)" : "rgba(111,247,255,0.035)";
      ctx.lineWidth = 1 + i * 0.4;
      ctx.stroke();
    }
    const eq = ctx.createLinearGradient(0, cy - s * 0.3, 0, cy + s * 0.3);
    eq.addColorStop(0, "rgba(255,255,255,0)");
    eq.addColorStop(0.5, "rgba(255,255,255,0.52)");
    eq.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = eq;
    ctx.fillRect(0, 0, s, s);
  });
}

function createGlowTexture(color = "255,255,255") {
  return canvasTexture(128, (ctx, s) => {
    const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
    g.addColorStop(0, `rgba(${color},1)`);
    g.addColorStop(0.16, `rgba(${color},0.9)`);
    g.addColorStop(0.5, `rgba(${color},0.25)`);
    g.addColorStop(1, `rgba(${color},0)`);
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
  });
}

function makeEnvironment(renderer) {
  const canvas = document.createElement("canvas");
  canvas.width = 1600;
  canvas.height = 800;
  const ctx = canvas.getContext("2d");

  const bg = ctx.createLinearGradient(0, 0, 0, 800);
  bg.addColorStop(0, "#08000f");
  bg.addColorStop(0.4, "#1a0329");
  bg.addColorStop(0.55, "#4b0b53");
  bg.addColorStop(0.7, "#12021d");
  bg.addColorStop(1, "#020005");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, 1600, 800);

  // Broad bright panels to create chrome highlights
  const panels = [
    { x: 180, y: 80, w: 420, h: 110, c: "#ff43b7", a: 0.9 },
    { x: 1000, y: 70, w: 380, h: 130, c: "#6ff7ff", a: 0.8 },
    { x: 620, y: 250, w: 310, h: 80, c: "#ffffff", a: 0.95 },
    { x: 40, y: 450, w: 310, h: 180, c: "#7a2cff", a: 0.65 },
    { x: 1220, y: 430, w: 320, h: 220, c: "#ff7adf", a: 0.55 },
    { x: 690, y: 580, w: 260, h: 100, c: "#d8ff5e", a: 0.35 },
  ];
  panels.forEach((p) => {
    const g = ctx.createRadialGradient(p.x + p.w / 2, p.y + p.h / 2, 0, p.x + p.w / 2, p.y + p.h / 2, p.w);
    g.addColorStop(0, p.c);
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.globalAlpha = p.a;
    ctx.fillStyle = g;
    ctx.fillRect(p.x - p.w / 2, p.y - p.h / 2, p.w * 2, p.h * 2);
  });
  ctx.globalAlpha = 1;

  // Thin light strips
  ctx.globalCompositeOperation = "lighter";
  const strips = [
    { y: 330, h: 4, c: "rgba(255,255,255,0.9)" },
    { y: 357, h: 2, c: "rgba(255,70,190,0.9)" },
    { y: 382, h: 2, c: "rgba(111,247,255,0.65)" },
  ];
  strips.forEach((s) => {
    const g = ctx.createLinearGradient(0, 0, 1600, 0);
    g.addColorStop(0, "rgba(0,0,0,0)");
    g.addColorStop(0.2, s.c);
    g.addColorStop(0.8, s.c);
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, s.y, 1600, s.h);
  });
  ctx.globalCompositeOperation = "source-over";

  const tex = new THREE.CanvasTexture(canvas);
  tex.mapping = THREE.EquirectangularReflectionMapping;
  tex.colorSpace = THREE.SRGBColorSpace;
  const pmrem = new THREE.PMREMGenerator(renderer);
  pmrem.compileEquirectangularShader();
  const env = pmrem.fromEquirectangular(tex).texture;
  tex.dispose();
  pmrem.dispose();
  return env;
}

export class World {
  constructor(scene, camera, renderer) {
    this.scene = scene;
    this.camera = camera;
    this.renderer = renderer;
    this.time = 0;
    this.palette = {
      accent: new THREE.Color("#ff3fba"),
      accent2: new THREE.Color("#6ff7ff"),
      accent3: new THREE.Color("#b897ff"),
      acid: new THREE.Color("#d8ff5e"),
    };
    this.targetPalette = {
      accent: this.palette.accent.clone(),
      accent2: this.palette.accent2.clone(),
      accent3: this.palette.accent3.clone(),
      acid: this.palette.acid.clone(),
    };
    this.shake = 0;
    this.destruction = 0;
    this.build();
  }

  build() {
    this.scene.environment = makeEnvironment(this.renderer);

    this.scene.fog = new THREE.FogExp2(0x08000f, 0.022);

    this.ambient = new THREE.AmbientLight(0x5a2b80, 0.8);
    this.scene.add(this.ambient);

    const key = new THREE.PointLight(0xff5bc8, 65, 22, 2);
    key.position.set(4.2, 5.6, 5.2);
    this.scene.add(key);
    this.keyLight = key;

    const fill = new THREE.PointLight(0x62eaff, 44, 20, 2);
    fill.position.set(-4.4, 3.2, 3.6);
    this.scene.add(fill);
    this.fillLight = fill;

    const rim = new THREE.PointLight(0xc9a5ff, 85, 18, 2);
    rim.position.set(1.5, 4.5, -4.5);
    this.scene.add(rim);
    this.rimLight = rim;

    const floorLight = new THREE.PointLight(0xff3fba, 22, 9, 2);
    floorLight.position.set(0, 0.45, 1.2);
    this.scene.add(floorLight);
    this.floorLight = floorLight;

    this.buildSky();
    this.buildSun();
    this.buildFloor();
    this.buildSet();
    this.buildDust();
  }

  buildSky() {
    const geo = new THREE.SphereGeometry(38, 48, 32);
    this.skyMat = new THREE.ShaderMaterial({
      uniforms: {
        uTop: { value: new THREE.Color("#030006") },
        uBottom: { value: new THREE.Color("#1c0329") },
        uAccent: { value: this.palette.accent.clone() },
        uAccent2: { value: this.palette.accent2.clone() },
        uTime: { value: 0 },
      },
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform vec3 uTop;
        uniform vec3 uBottom;
        uniform vec3 uAccent;
        uniform vec3 uAccent2;
        uniform float uTime;
        varying vec3 vWorld;
        float hash(vec2 p) {
          p = fract(p * vec2(123.34, 456.21));
          p += dot(p, p + 45.32);
          return fract(p.x * p.y);
        }
        void main() {
          vec3 d = normalize(vWorld);
          float h = clamp(d.y * 0.5 + 0.5, 0.0, 1.0);
          vec3 col = mix(uBottom, uTop, smoothstep(0.05, 0.85, h));
          float horizon = exp(-pow((d.y + 0.035) * 5.4, 2.0));
          col += uAccent * horizon * 0.28;
          float ang = atan(d.z, d.x);
          float beams = pow(max(0.0, sin(ang * 19.0 + uTime * 0.045)), 24.0);
          beams *= smoothstep(0.35, 0.02, abs(d.y - 0.2));
          col += mix(uAccent, uAccent2, 0.5) * beams * 0.07;
          float upper = smoothstep(0.08, 0.95, d.y);
          col += uAccent2 * upper * 0.018;
          float grain = hash(gl_FragCoord.xy + uTime) * 0.012;
          gl_FragColor = vec4(col + grain, 1.0);
        }
      `,
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
    });
    this.sky = new THREE.Mesh(geo, this.skyMat);
    this.scene.add(this.sky);

    // Stars
    const count = 900;
    const positions = new Float32Array(count * 3);
    const colors = new Float32Array(count * 3);
    const color = new THREE.Color();
    for (let i = 0; i < count; i++) {
      const r = 18 + Math.random() * 16;
      const theta = Math.random() * TAU;
      const phi = Math.acos(THREE.MathUtils.randFloatSpread(2));
      positions[i * 3] = Math.sin(phi) * Math.cos(theta) * r;
      positions[i * 3 + 1] = Math.cos(phi) * r * 0.7 + 3;
      positions[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * r;
      color.set(i % 7 === 0 ? "#ff91dd" : i % 5 === 0 ? "#8df9ff" : "#f3eaff");
      color.multiplyScalar(0.35 + Math.random() * 0.65);
      colors[i * 3] = color.r;
      colors[i * 3 + 1] = color.g;
      colors[i * 3 + 2] = color.b;
    }
    const starGeo = new THREE.BufferGeometry();
    starGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    starGeo.setAttribute("color", new THREE.BufferAttribute(colors, 3));
    this.stars = new THREE.Points(
      starGeo,
      new THREE.PointsMaterial({
        size: 0.055,
        sizeAttenuation: true,
        vertexColors: true,
        transparent: true,
        opacity: 0.85,
        depthWrite: false,
        blending: THREE.AdditiveBlending,
        map: createGlowTexture("255,255,255"),
        toneMapped: false,
      })
    );
    this.scene.add(this.stars);
  }

  buildSun() {
    const tex = createSunTexture();
    this.sunMat = new THREE.SpriteMaterial({
      map: tex,
      color: "#ffffff",
      transparent: true,
      opacity: 0.92,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      depthTest: false,
      toneMapped: false,
    });
    this.sun = new THREE.Sprite(this.sunMat);
    this.sun.position.set(0.35, 2.85, -9.5);
    this.sun.scale.set(10.5, 10.5, 1);
    this.sun.renderOrder = -2;
    this.scene.add(this.sun);

    // A dark eclipse disc in front of the sun
    const eclipse = new THREE.Mesh(
      new THREE.CircleGeometry(1.23, 100),
      new THREE.MeshBasicMaterial({ color: "#08000f", transparent: true, opacity: 0.9 })
    );
    eclipse.position.set(0.35, 2.85, -9.47);
    eclipse.renderOrder = -1;
    this.scene.add(eclipse);
    this.eclipse = eclipse;

    const ringMat = new THREE.MeshBasicMaterial({
      color: "#ff70cf",
      transparent: true,
      opacity: 0.6,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    this.portalRings = [];
    [
      [1.55, 0.008],
      [2.3, 0.005],
      [3.2, 0.004],
    ].forEach(([r, tube], i) => {
      const ring = new THREE.Mesh(new THREE.TorusGeometry(r, tube, 4, 180), ringMat.clone());
      ring.position.set(0.35, 2.85, -9.44 + i * 0.01);
      ring.userData.spin = (i + 1) * 0.025 * (i % 2 ? -1 : 1);
      this.scene.add(ring);
      this.portalRings.push(ring);
    });

    // Giant architectural arcs behind the scene
    const arcMat = new THREE.MeshBasicMaterial({
      color: "#b06bff",
      transparent: true,
      opacity: 0.31,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      toneMapped: false,
    });
    this.bigRings = [];
    [
      { r: 5.1, y: 2.2, z: -4.8, rot: 0.05, color: "#b06bff", opacity: 0.22 },
      { r: 6.4, y: 1.9, z: -6.3, rot: -0.11, color: "#6ff7ff", opacity: 0.16 },
    ].forEach((spec, i) => {
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(spec.r, 0.014, 5, 200),
        new THREE.MeshBasicMaterial({
          color: spec.color,
          transparent: true,
          opacity: spec.opacity,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        })
      );
      ring.position.set(0.4, spec.y, spec.z);
      ring.rotation.z = spec.rot;
      ring.userData.spin = i % 2 ? -0.014 : 0.01;
      this.scene.add(ring);
      this.bigRings.push(ring);
    });
  }

  buildFloor() {
    const floorMat = new THREE.MeshPhysicalMaterial({
      color: 0x06010b,
      metalness: 1,
      roughness: 0.09,
      clearcoat: 1,
      clearcoatRoughness: 0.06,
      envMapIntensity: 1.4,
    });
    const floor = new THREE.Mesh(new THREE.CircleGeometry(26, 128), floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0;
    this.scene.add(floor);
    this.floor = floor;

    // Glowing grid
    const gridMat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: this.palette.accent.clone() },
        uColorB: { value: this.palette.accent2.clone() },
        uOpacity: { value: 0.48 },
      },
      vertexShader: `
        varying vec3 vWorld;
        void main() {
          vec4 wp = modelMatrix * vec4(position, 1.0);
          vWorld = wp.xyz;
          gl_Position = projectionMatrix * viewMatrix * wp;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        uniform float uOpacity;
        varying vec3 vWorld;
        float lineMask(vec2 p, float scale) {
          vec2 q = abs(fract(p * scale - 0.5) - 0.5) / max(fwidth(p * scale), vec2(0.0001));
          return 1.0 - min(min(q.x, q.y), 1.0);
        }
        void main() {
          float r = length(vWorld.xz);
          float fade = smoothstep(22.0, 1.0, r);
          float major = lineMask(vWorld.xz, 0.5);
          float minor = lineMask(vWorld.xz, 2.0);
          float pulse = 0.75 + 0.25 * sin(r * 1.8 - uTime * 1.1);
          vec3 col = mix(uColorA, uColorB, 0.5 + 0.5 * sin(vWorld.x * 0.2 + vWorld.z * 0.17));
          float alpha = (major * 0.22 + minor * 0.06) * fade * pulse * uOpacity;
          gl_FragColor = vec4(col * (1.8 + major * 1.5), alpha);
        }
      `,
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide,
      extensions: { derivatives: true },
    });
    const grid = new THREE.Mesh(new THREE.PlaneGeometry(50, 50, 1, 1), gridMat);
    grid.rotation.x = -Math.PI / 2;
    grid.position.y = 0.011;
    this.scene.add(grid);
    this.grid = grid;
    this.gridMat = gridMat;

    // Stage
    const stageMat = new THREE.MeshPhysicalMaterial({
      color: 0x1b0727,
      metalness: 0.95,
      roughness: 0.08,
      clearcoat: 1,
      clearcoatRoughness: 0.03,
      envMapIntensity: 2,
    });
    const stage = new THREE.Mesh(new THREE.CylinderGeometry(1.12, 1.26, 0.16, 96), stageMat);
    stage.position.y = 0.08;
    this.scene.add(stage);
    this.stage = stage;

    const stageTop = new THREE.Mesh(
      new THREE.CircleGeometry(1.115, 96),
      new THREE.MeshPhysicalMaterial({
        color: 0x0a0110,
        metalness: 1,
        roughness: 0.04,
        envMapIntensity: 2.1,
      })
    );
    stageTop.rotation.x = -Math.PI / 2;
    stageTop.position.y = 0.161;
    this.scene.add(stageTop);

    const stageRing = new THREE.Mesh(
      new THREE.TorusGeometry(1.16, 0.012, 6, 120),
      new THREE.MeshBasicMaterial({
        color: "#6ff7ff",
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      })
    );
    stageRing.rotation.x = Math.PI / 2;
    stageRing.position.y = 0.164;
    this.scene.add(stageRing);
    this.stageRing = stageRing;

    // Ripple rings on the floor
    this.ripples = [];
    for (let i = 0; i < 7; i++) {
      const mat = new THREE.MeshBasicMaterial({
        color: i % 2 ? "#6ff7ff" : "#ff3fba",
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      });
      const ring = new THREE.Mesh(new THREE.TorusGeometry(1, 0.004, 4, 180), mat);
      ring.rotation.x = Math.PI / 2;
      ring.position.y = 0.02;
      ring.userData.offset = i / 7;
      this.scene.add(ring);
      this.ripples.push(ring);
    }
  }

  buildSet() {
    this.setGroup = new THREE.Group();
    this.scene.add(this.setGroup);

    const chrome = new THREE.MeshPhysicalMaterial({
      color: "#eef6ff",
      metalness: 1,
      roughness: 0.06,
      clearcoat: 1,
      envMapIntensity: 2.2,
    });

    // Slender chrome pillars framing the goddess
    const pillarPositions = [
      [-3.6, 2.1, -2.2, 0.22],
      [3.8, 2.0, -2.6, 0.16],
      [-4.8, 1.8, -4.5, 0.11],
      [4.9, 1.7, -4.8, 0.1],
    ];
    pillarPositions.forEach(([x, y, z, r]) => {
      const h = 4.6;
      const pillar = new THREE.Mesh(new THREE.CylinderGeometry(r, r * 1.4, h, 16), chrome);
      pillar.position.set(x, y, z);
      pillar.rotation.z = x * 0.008;
      this.setGroup.add(pillar);

      const ring = new THREE.Mesh(new THREE.TorusGeometry(r * 1.8, 0.015, 6, 30), this.gridMat);
      ring.rotation.x = Math.PI / 2;
      ring.position.set(x, 0.18, z);
      this.setGroup.add(ring);
    });

    // Floating shards and monoliths
    this.shards = [];
    const shardGeo = [
      new THREE.OctahedronGeometry(0.4, 0),
      new THREE.TetrahedronGeometry(0.32, 0),
      new THREE.IcosahedronGeometry(0.26, 0),
      new THREE.BoxGeometry(0.18, 0.9, 0.18),
    ];
    for (let i = 0; i < 18; i++) {
      const geo = shardGeo[i % shardGeo.length];
      const mat = i % 5 === 0
        ? new THREE.MeshBasicMaterial({ color: i % 2 ? "#ff3fba" : "#6ff7ff", transparent: true, opacity: 0.4, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
        : chrome;
      const mesh = new THREE.Mesh(geo, mat);
      const a = (i / 18) * TAU + 0.4;
      const r = 3.2 + Math.random() * 4.4;
      mesh.position.set(Math.sin(a) * r, 0.6 + Math.random() * 4.6, Math.cos(a) * r * 0.7 - 2.4);
      mesh.rotation.set(Math.random() * TAU, Math.random() * TAU, Math.random() * TAU);
      mesh.userData = {
        baseY: mesh.position.y,
        phase: Math.random() * TAU,
        spin: 0.02 + Math.random() * 0.09,
        bob: 0.08 + Math.random() * 0.2,
        scale: 0.6 + Math.random() * 1.3,
      };
      mesh.scale.setScalar(mesh.userData.scale);
      this.setGroup.add(mesh);
      this.shards.push(mesh);
    }

    // A trio of holographic hoops at the side
    this.hoops = [];
    [0, 1, 2].forEach((i) => {
      const hoop = new THREE.Mesh(
        new THREE.TorusGeometry(0.55 + i * 0.35, 0.006, 4, 100),
        new THREE.MeshBasicMaterial({
          color: i === 1 ? "#ff3fba" : "#6ff7ff",
          transparent: true,
          opacity: 0.33 - i * 0.06,
          blending: THREE.AdditiveBlending,
          depthWrite: false,
          toneMapped: false,
        })
      );
      hoop.position.set(-3.9 + i * 0.36, 2.3 + i * 0.2, -3.7 - i * 0.3);
      hoop.rotation.set(0.8 + i * 0.25, 0.3, 0.4 + i * 0.2);
      hoop.userData.phase = i * 1.6;
      this.setGroup.add(hoop);
      this.hoops.push(hoop);
    });
  }

  buildDust() {
    const count = 1400;
    const positions = new Float32Array(count * 3);
    const sizes = new Float32Array(count);
    const phases = new Float32Array(count);
    for (let i = 0; i < count; i++) {
      const r = 1.2 + Math.pow(Math.random(), 0.55) * 9;
      const a = Math.random() * TAU;
      positions[i * 3] = Math.sin(a) * r;
      positions[i * 3 + 1] = Math.random() * 6.5;
      positions[i * 3 + 2] = Math.cos(a) * r * 0.75;
      sizes[i] = 0.02 + Math.random() * 0.075;
      phases[i] = Math.random() * TAU;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    geo.setAttribute("aSize", new THREE.BufferAttribute(sizes, 1));
    geo.setAttribute("aPhase", new THREE.BufferAttribute(phases, 1));

    const mat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColor: { value: this.palette.accent.clone() },
        uColor2: { value: this.palette.accent2.clone() },
        uPixelRatio: { value: Math.min(window.devicePixelRatio, 2) },
      },
      vertexShader: `
        attribute float aSize;
        attribute float aPhase;
        uniform float uTime;
        uniform float uPixelRatio;
        varying float vAlpha;
        varying float vMix;
        void main() {
          vec3 pos = position;
          pos.y += sin(uTime * 0.25 + aPhase) * 0.32;
          pos.x += cos(uTime * 0.15 + aPhase) * 0.13;
          vec4 mv = modelViewMatrix * vec4(pos, 1.0);
          gl_PointSize = aSize * 280.0 * uPixelRatio / max(-mv.z, 1.0);
          gl_Position = projectionMatrix * mv;
          vAlpha = 0.22 + 0.55 * (0.5 + 0.5 * sin(uTime * 0.9 + aPhase * 3.0));
          vMix = 0.5 + 0.5 * sin(aPhase * 2.4 + uTime * 0.2);
        }
      `,
      fragmentShader: `
        uniform vec3 uColor;
        uniform vec3 uColor2;
        varying float vAlpha;
        varying float vMix;
        void main() {
          vec2 c = gl_PointCoord - 0.5;
          float d = length(c);
          float core = smoothstep(0.5, 0.0, d);
          float glow = smoothstep(0.5, 0.05, d) * 0.28;
          vec3 col = mix(uColor, uColor2, vMix);
          gl_FragColor = vec4(col, (core + glow) * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
    });
    this.dust = new THREE.Points(geo, mat);
    this.dust.sortParticles = true;
    this.scene.add(this.dust);
  }

  setPalette(palette) {
    if (palette.accent) this.targetPalette.accent.set(palette.accent);
    if (palette.accent2) this.targetPalette.accent2.set(palette.accent2);
    if (palette.accent3) this.targetPalette.accent3.set(palette.accent3);
    if (palette.acid) this.targetPalette.acid.set(palette.acid);
  }

  pulse(strength = 1) {
    this.destruction = Math.max(this.destruction, strength);
    this.shake = Math.max(this.shake, strength);
    this.ripples.forEach((ring, i) => {
      ring.userData.offset = (i / this.ripples.length + Math.random() * 0.04) % 1;
    });
  }

  update(dt, t) {
    this.time = t;
    this.palette.accent.lerp(this.targetPalette.accent, dt * 2);
    this.palette.accent2.lerp(this.targetPalette.accent2, dt * 2);
    this.palette.accent3.lerp(this.targetPalette.accent3, dt * 2);
    this.palette.acid.lerp(this.targetPalette.acid, dt * 2);

    this.skyMat.uniforms.uTime.value = t;
    this.skyMat.uniforms.uAccent.value.copy(this.palette.accent);
    this.skyMat.uniforms.uAccent2.value.copy(this.palette.accent2);
    this.gridMat.uniforms.uTime.value = t;
    this.gridMat.uniforms.uColorA.value.copy(this.palette.accent);
    this.gridMat.uniforms.uColorB.value.copy(this.palette.accent2);
    this.dust.material.uniforms.uTime.value = t;
    this.dust.material.uniforms.uColor.value.copy(this.palette.accent);
    this.dust.material.uniforms.uColor2.value.copy(this.palette.accent2);
    this.stars.rotation.y = t * 0.003;
    this.sunMat.opacity = 0.82 + Math.sin(t * 0.7) * 0.07;
    this.eclipse.scale.setScalar(1 + Math.sin(t * 0.4) * 0.018);
    this.portalRings.forEach((ring) => {
      ring.rotation.z += dt * ring.userData.spin;
      ring.material.opacity = 0.32 + Math.sin(t * 0.5 + ring.userData.spin * 100) * 0.16;
      ring.material.color.copy(this.palette.accent);
    });
    this.bigRings.forEach((ring) => {
      ring.rotation.z += dt * ring.userData.spin;
    });
    this.stageRing.material.opacity = 0.58 + Math.sin(t * 1.2) * 0.22;
    this.stageRing.material.color.copy(this.palette.accent2);

    this.shards.forEach((mesh) => {
      const u = mesh.userData;
      mesh.rotation.x += dt * u.spin;
      mesh.rotation.y += dt * u.spin * 0.66;
      mesh.position.y = u.baseY + Math.sin(t * 0.42 + u.phase) * u.bob;
      if (mesh.material.transparent) mesh.material.opacity = 0.22 + Math.sin(t * 0.8 + u.phase) * 0.16;
    });
    this.hoops.forEach((hoop) => {
      hoop.rotation.z += dt * 0.08;
      hoop.rotation.y += dt * 0.03;
      hoop.material.opacity = 0.2 + Math.sin(t * 0.55 + hoop.userData.phase) * 0.1;
    });

    this.ripples.forEach((ring) => {
      const u = ring.userData;
      u.offset = (u.offset + dt * 0.12) % 1;
      const s = 1 + u.offset * 8;
      ring.scale.setScalar(s);
      ring.material.opacity = (1 - u.offset) * 0.22;
      ring.material.color.copy(u.offset > 0.5 ? this.palette.accent : this.palette.accent2);
    });

    if (this.destruction > 0.001) {
      this.destruction = Math.max(0, this.destruction - dt * 1.1);
      const d = this.destruction;
      this.setGroup.rotation.z = Math.sin(t * 45) * 0.006 * d;
      this.sunMat.opacity = 0.82 + d * 0.2;
      this.floor.position.x = THREE.MathUtils.randFloatSpread(0.05) * d;
      this.floor.position.z = THREE.MathUtils.randFloatSpread(0.05) * d;
    } else {
      this.setGroup.rotation.z = 0;
      this.floor.position.x = 0;
      this.floor.position.z = 0;
    }

    // camera shake is applied by main
    this.shake = Math.max(0, this.shake - dt * 1.8);
  }

  getShakeOffset() {
    if (this.shake <= 0.001) return new THREE.Vector3();
    const s = this.shake * this.shake * 0.06;
    return new THREE.Vector3(THREE.MathUtils.randFloatSpread(s), THREE.MathUtils.randFloatSpread(s), 0);
  }
}

