630:   buildArm(shoulder, elbow, wrist, fingersUp, side) {
631:     const arm = new THREE.Group();
632:     arm.position.copy(shoulder);
633:     arm.userData.baseRotation = arm.rotation.clone();
634:     arm.userData.side = side;
635:     this.group.add(arm);
636:     this.armGroups.push(arm);
637: 
638:     const localElbow = elbow.clone().sub(shoulder);
639:     const localWrist = wrist.clone().sub(shoulder);
640: 
641:     const shoulderBall = this.add(new THREE.Mesh(new THREE.SphereGeometry(0.105, 22, 16), this.skin), arm);
642:     shoulderBall.scale.set(1, 0.95, 0.95);
643: 
644:     arm.add(makeLimb(new THREE.Vector3(0, 0, 0), localElbow, 0.082, 0.06, this.skin));
645:     const elbowBall = this.add(new THREE.Mesh(new THREE.SphereGeometry(0.062, 18, 12), this.skin), arm);
646:     elbowBall.position.copy(localElbow);
647: 
648:     const forearm = makeLimb(localElbow, localWrist, 0.058, 0.038, this.skin);
649:     arm.add(forearm);
650: 
651:     const wristBall = this.add(new THREE.Mesh(new THREE.SphereGeometry(0.043, 16, 12), this.skin), arm);
652:     wristBall.position.copy(localWrist);
653: 
654:     const hand = makeHand(fingersUp);
655:     hand.children.forEach((child) => {
656:       if (child.isMesh) child.material = this.skin;
657:     });
658:     hand.position.copy(localWrist);
659:     const handDir = localWrist.clone().sub(localElbow).normalize();
660:     hand.quaternion.setFromUnitVectors(Y, handDir);
661:     hand.rotateY(side * 0.25);
662:     arm.add(hand);
663: 
664:     // Chrome cuff and bracelets
665:     const cuffDir = localWrist.clone().sub(localElbow);
666:     const cuff = this.add(new THREE.Mesh(new THREE.TorusGeometry(0.045, 0.012, 8, 24), this.chrome), arm);
667:     cuff.position.copy(localWrist).addScaledVector(cuffDir.normalize(), -0.045);
668:     cuff.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), cuffDir);
669: 
670:     const upperCuff = this.add(new THREE.Mesh(new THREE.TorusGeometry(0.075, 0.012, 8, 28), this.chrome), arm);
671:     upperCuff.position.copy(localElbow).addScaledVector(localElbow.clone().normalize(), -0.12);
672:     upperCuff.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), localElbow.clone().normalize());
673: 
674:     // Shoulder armour
675:     const shoulderGem = this.add(new THREE.Mesh(new THREE.OctahedronGeometry(0.055, 0), this.chrome), arm);
676:     shoulderGem.position.set(-side * 0.01, 0.02, 0.085);
677:     shoulderGem.rotation.z = 0.3;
678: 
679:     return arm;
680:   }
