729:   buildDress() {
730:     // A short, sculpted skirt with a high front slit and a long liquid train.
731:     const yTop = 2.12;
732:     const segmentsU = 80;
733:     const segmentsV = 14;
734:     const phiStart = 0.38;
735:     const phiLength = 5.56;
736:     const positions = [];
737:     const uvs = [];
738:     const indices = [];
739: 
740:     for (let iv = 0; iv <= segmentsV; iv++) {
741:       const v = iv / segmentsV;
742:       for (let iu = 0; iu <= segmentsU; iu++) {
743:         const u = iu / segmentsU;
744:         const phi = phiStart + u * phiLength;
745:         const frontness = 0.5 + 0.5 * Math.cos(phi);
746:         const hemY = lerp(0.98, 1.62, frontness);
747:         const y = lerp(yTop, hemY, Math.pow(v, 0.94));
748:         const radius = lerp(0.255, 0.51, Math.pow(v, 1.45));
749:         const ripple = Math.sin(u * Math.PI * 7 + v * 5.2) * 0.022 * v;
750:         positions.push(Math.sin(phi) * (radius + ripple), y, Math.cos(phi) * (radius + ripple) * 0.92);
751:         uvs.push(u, v);
752:       }
753:     }
754:     for (let iv = 0; iv < segmentsV; iv++) {
755:       for (let iu = 0; iu < segmentsU; iu++) {
756:         const a = iv * (segmentsU + 1) + iu;
757:         const b = a + 1;
758:         const c = a + segmentsU + 1;
759:         const d = c + 1;
760:         indices.push(a, c, b, b, c, d);
761:       }
762:     }
763:     const skirtGeo = new THREE.BufferGeometry();
764:     skirtGeo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
765:     skirtGeo.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
766:     skirtGeo.setIndex(indices);
767:     skirtGeo.computeVertexNormals();
768: 
769:     this.skirt = this.add(new THREE.Mesh(skirtGeo, this.fabricMat));
770:     this.skirt.renderOrder = 1;
771:     this.skirtBase = skirtGeo.attributes.position.array.slice();
772:     this.dressMeshes.push(this.skirt);
773: 
774:     // Liquid train, built as a wide rippling sheet behind her.
775:     const trainU = 32;
776:     const trainV = 18;
777:     const trainPositions = [];
778:     const trainUvs = [];
779:     const trainIndices = [];
780:     for (let iv = 0; iv <= trainV; iv++) {
781:       const v = iv / trainV;
782:       for (let iu = 0; iu <= trainU; iu++) {
783:         const u = iu / trainU - 0.5;
784:         const width = 0.42 + v * 1.35;
785:         const x = u * width * 2 + Math.sin(v * 7.5 + u * 5) * 0.08 * v;
786:         const y = lerp(2.12, 0.035, v);
787:         const z = -0.2 - v * 0.82 - Math.cos(u * Math.PI) * 0.2 * v + Math.sin(v * 4.5) * 0.05;
788:         trainPositions.push(x, y, z);
789:         trainUvs.push(iu / trainU, v);
790:       }
791:     }
792:     for (let iv = 0; iv < trainV; iv++) {
793:       for (let iu = 0; iu < trainU; iu++) {
794:         const a = iv * (trainU + 1) + iu;
795:         const b = a + 1;
796:         const c = a + trainU + 1;
797:         const d = c + 1;
798:         trainIndices.push(a, c, b, b, c, d);
799:       }
800:     }
801:     const trainGeo = new THREE.BufferGeometry();
802:     trainGeo.setAttribute("position", new THREE.Float32BufferAttribute(trainPositions, 3));
803:     trainGeo.setAttribute("uv", new THREE.Float32BufferAttribute(trainUvs, 2));
804:     trainGeo.setIndex(trainIndices);
805:     trainGeo.computeVertexNormals();
806: 
807:     const trainMat = this.makeMaterial({
808:       color: "#4d0b6e",
809:       roughness: 0.2,
810:       metalness: 0.62,
811:       transparent: true,
812:       opacity: 0.34,
813:       side: THREE.DoubleSide,
814:       depthWrite: false,
815:       clearcoat: 1,
