1213:     this.chrome.color.lerp(this.targetPalette.chrome, dt * 1.8);
1214:     this.haloMat.emissive.lerp(this.targetPalette.accent2, dt * 1.8);
1215: 
1216:     // Idle breathing and contrapposto
1217:     const breath = Math.sin(t * 1.25);
1218:     this.group.position.y = breath * 0.012;
1219:     this.group.rotation.y = Math.sin(t * 0.35) * 0.045 + this.pointer.x * 0.075;
