1227:     this.headGroup.rotation.z = Math.sin(t * 0.38) * 0.02;
1228: 
1229:     // Arm life
1230:     const actionAge = this.action ? t - this.action.startedAt : 99;
1231:     let gesture = 0;
1232:     if (this.action && actionAge < 1.6) {
1233:       const p = actionAge / 1.6;
1234:       gesture = Math.sin(p * Math.PI) * 0.1;
1235:     }
1236:     this.armR.rotation.z = Math.sin(t * 0.7) * 0.018 + gesture;
1237:     this.armR.rotation.x = Math.sin(t * 0.55 + 1) * 0.016;
1238:     this.armL.rotation.z = Math.sin(t * 0.62 + 2) * 0.015 - gesture * 0.4;
1239:     this.armL.rotation.x = Math.sin(t * 0.48) * 0.015;
1240: 
1241:     // Halo motion
1242:     this.crownRing.rotation.z = t * 0.11;
1243:     this.crownRing2.rotation.z = -t * 0.18;
1244:     this.headHalo.rotation.z = t * 0.08;
1245:     this.headHalo.material.opacity = 0.38 + Math.sin(t * 0.9) * 0.12;
1246:     this.haloMat.emissiveIntensity = 0.8 + Math.sin(t * 1.1) * 0.25;
1247: 
1248:     this.rings.forEach((ring) => {
1249:       const d = ring.userData;
1250:       ring.rotation.z = d.baseRz + Math.sin(t * d.speed + d.phase) * 0.12;
1251:       ring.rotation.x = d.baseRx + Math.cos(t * d.speed * 0.8 + d.phase) * 0.035;
1252:       ring.material.opacity = 0.32 + Math.sin(t * 0.5 + d.phase) * 0.1;
1253:     });
1254: 
1255:     this.satellites.forEach(({ mesh, kind }) => {
1256:       const u = mesh.userData;
1257:       if (kind === "sat") {
1258:         const ang = u.angle + t * u.speed;
1259:         mesh.position.set(Math.cos(ang) * u.radius, u.ring.position.y + Math.sin(ang * 2) * 0.04, Math.sin(ang) * u.radius);
1260:         mesh.rotation.x = t * 0.7;
1261:         mesh.rotation.y = t * 0.9;
1262:       } else if (kind === "crown") {
1263:         const ang = u.angle + t * u.speed;
1264:         mesh.position.set(Math.sin(ang) * u.radius, u.y + Math.sin(ang * 3 + t) * 0.018, Math.cos(ang) * u.radius);
1265:         mesh.rotation.y = t * 0.4;
