49: function createGlowTexture(color = "255,255,255") {
50:   return canvasTexture(128, (ctx, s) => {
51:     const g = ctx.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
52:     g.addColorStop(0, `rgba(${color},1)`);
53:     g.addColorStop(0.16, `rgba(${color},0.9)`);
54:     g.addColorStop(0.5, `rgba(${color},0.25)`);
55:     g.addColorStop(1, `rgba(${color},0)`);
56:     ctx.fillStyle = g;
57:     ctx.fillRect(0, 0, s, s);
58:   });
59: }
