61: function makeEnvironment(renderer) {
62:   const canvas = document.createElement("canvas");
63:   canvas.width = 1600;
64:   canvas.height = 800;
65:   const ctx = canvas.getContext("2d");
66: 
67:   const bg = ctx.createLinearGradient(0, 0, 0, 800);
68:   bg.addColorStop(0, "#08000f");
69:   bg.addColorStop(0.4, "#1a0329");
70:   bg.addColorStop(0.55, "#4b0b53");
71:   bg.addColorStop(0.7, "#12021d");
72:   bg.addColorStop(1, "#020005");
73:   ctx.fillStyle = bg;
74:   ctx.fillRect(0, 0, 1600, 800);
75: 
76:   // Broad bright panels to create chrome highlights
77:   const panels = [
78:     { x: 180, y: 80, w: 420, h: 110, c: "#ff43b7", a: 0.9 },
79:     { x: 1000, y: 70, w: 380, h: 130, c: "#6ff7ff", a: 0.8 },
80:     { x: 620, y: 250, w: 310, h: 80, c: "#ffffff", a: 0.95 },
81:     { x: 40, y: 450, w: 310, h: 180, c: "#7a2cff", a: 0.65 },
82:     { x: 1220, y: 430, w: 320, h: 220, c: "#ff7adf", a: 0.55 },
83:     { x: 690, y: 580, w: 260, h: 100, c: "#d8ff5e", a: 0.35 },
84:   ];
85:   panels.forEach((p) => {
86:     const g = ctx.createRadialGradient(p.x + p.w / 2, p.y + p.h / 2, 0, p.x + p.w / 2, p.y + p.h / 2, p.w);
87:     g.addColorStop(0, p.c);
88:     g.addColorStop(1, "rgba(0,0,0,0)");
89:     ctx.globalAlpha = p.a;
90:     ctx.fillStyle = g;
91:     ctx.fillRect(p.x - p.w / 2, p.y - p.h / 2, p.w * 2, p.h * 2);
92:   });
93:   ctx.globalAlpha = 1;
94: 
95:   // Thin light strips
96:   ctx.globalCompositeOperation = "lighter";
97:   const strips = [
98:     { y: 330, h: 4, c: "rgba(255,255,255,0.9)" },
99:     { y: 357, h: 2, c: "rgba(255,70,190,0.9)" },
100:     { y: 382, h: 2, c: "rgba(111,247,255,0.65)" },
101:   ];
102:   strips.forEach((s) => {
103:     const g = ctx.createLinearGradient(0, 0, 1600, 0);
104:     g.addColorStop(0, "rgba(0,0,0,0)");
105:     g.addColorStop(0.2, s.c);
106:     g.addColorStop(0.8, s.c);
107:     g.addColorStop(1, "rgba(0,0,0,0)");
108:     ctx.fillStyle = g;
109:     ctx.fillRect(0, s.y, 1600, s.h);
110:   });
111:   ctx.globalCompositeOperation = "source-over";
112: 
113:   const tex = new THREE.CanvasTexture(canvas);
114:   tex.mapping = THREE.EquirectangularReflectionMapping;
115:   tex.colorSpace = THREE.SRGBColorSpace;
116:   const pmrem = new THREE.PMREMGenerator(renderer);
117:   pmrem.compileEquirectangularShader();
118:   const env = pmrem.fromEquirectangular(tex).texture;
119:   tex.dispose();
120:   pmrem.dispose();
121:   return env;
122: }
