188:         uAccent: { value: this.palette.accent.clone() },
189:         uAccent2: { value: this.palette.accent2.clone() },
190:         uTime: { value: 0 },
191:       },
192:       vertexShader: `
193:         varying vec3 vWorld;
194:         void main() {
195:           vec4 wp = modelMatrix * vec4(position, 1.0);
196:           vWorld = wp.xyz;
197:           gl_Position = projectionMatrix * viewMatrix * wp;
198:         }
199:       `,
200:       fragmentShader: `
201:         uniform vec3 uTop;
202:         uniform vec3 uBottom;
203:         uniform vec3 uAccent;
204:         uniform vec3 uAccent2;
205:         uniform float uTime;
206:         varying vec3 vWorld;
207:         float hash(vec2 p) {
208:           p = fract(p * vec2(123.34, 456.21));
209:           p += dot(p, p + 45.32);
210:           return fract(p.x * p.y);
211:         }
212:         void main() {
213:           vec3 d = normalize(vWorld);
214:           float h = clamp(d.y * 0.5 + 0.5, 0.0, 1.0);
215:           vec3 col = mix(uBottom, uTop, smoothstep(0.05, 0.85, h));
216:           float horizon = exp(-pow((d.y + 0.035) * 5.4, 2.0));
217:           col += uAccent * horizon * 0.28;
218:           float ang = atan(d.z, d.x);
219:           float beams = pow(max(0.0, sin(ang * 19.0 + uTime * 0.045)), 24.0);
220:           beams *= smoothstep(0.35, 0.02, abs(d.y - 0.2));
221:           col += mix(uAccent, uAccent2, 0.5) * beams * 0.07;
222:           float upper = smoothstep(0.08, 0.95, d.y);
223:           col += uAccent2 * upper * 0.018;
224:           float grain = hash(gl_FragCoord.xy + uTime) * 0.012;
225:           gl_FragColor = vec4(col + grain, 1.0);
226:         }
227:       `,
228:       side: THREE.BackSide,
229:       depthWrite: false,
230:       fog: false,
231:     });
232:     this.sky = new THREE.Mesh(geo, this.skyMat);
233:     this.scene.add(this.sky);
