602:           pos.x += cos(uTime * 0.15 + aPhase) * 0.13;
603:           vec4 mv = modelViewMatrix * vec4(pos, 1.0);
604:           gl_PointSize = aSize * 280.0 * uPixelRatio / max(-mv.z, 1.0);
