612:         uniform vec3 uColor2;
613:         varying float vAlpha;
614:         varying float vMix;
615:         void main() {
616:           vec2 c = gl_PointCoord - 0.5;
617:           float d = length(c);
618:           float core = smoothstep(0.5, 0.0, d);
619:           float glow = smoothstep(0.5, 0.05, d) * 0.28;
620:           vec3 col = mix(uColor, uColor2, vMix);
621:           gl_FragColor = vec4(col, (core + glow) * vAlpha);
622:         }
