636:     if (palette.accent2) this.targetPalette.accent2.set(palette.accent2);
637:     if (palette.accent3) this.targetPalette.accent3.set(palette.accent3);
638:     if (palette.acid) this.targetPalette.acid.set(palette.acid);
639:   }
