function createSunTexture() {
  return canvasTexture(1024, (ctx, s) => {
    ctx.clearRect(0, 0, s, s);
    const cx = s / 2;
    const cy = s / 2;
    const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, s / 2);
    g.addColorStop(0, "rgba(255,246,255,1)");
    g.addColorStop(0.06, "rgba(255,190,246,1)");
    g.addColorStop(0.2, "rgba(255,64,187,0.88)");
    g.addColorStop(0.46, "rgba(120,32,255,0.28)");
    g.addColorStop(0.8, "rgba(46,5,76,0.04)");
    g.addColorStop(1, "rgba(0,0,0,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);

    ctx.globalCompositeOperation = "lighter";
    for (let i = 0; i < 7; i++) {
      ctx.beginPath();
      ctx.arc(cx, cy, s * (0.2 + i * 0.04), 0, TAU);
      ctx.strokeStyle = i % 2 ? "rgba(255,255,255,0.055)" : "rgba(111,247,255,0.035)";
      ctx.lineWidth = 1 + i * 0.4;
      ctx.stroke();
    }
    const eq = ctx.createLinearGradient(0, cy - s * 0.3, 0, cy + s * 0.3);
    eq.addColorStop(0, "rgba(255,255,255,0)");
    eq.addColorStop(0.5, "rgba(255,255,255,0.52)");
    eq.addColorStop(1, "rgba(255,255,255,0)");
    ctx.fillStyle = eq;
    ctx.fillRect(0, 0, s, s);
  });
}

